def reliability(p, y):
    idx = np.digitize(p, bins[1:-1])
    return np.array([(p[idx == b].mean(), y[idx == b].mean(), int((idx == b).sum())) if (idx == b).any() else (np.nan, np.nan, 0) for b in range(len(bins) - 1)])


